/**
 * The banner on every generated module. It says that the file is generated, that it is not to be edited or
 * committed, and where it comes from, because a generated file that does not say it is generated
 * is a file someone edits once and loses. It carries no copyright line: the file is made of the
 * project's own directories.
 */
export const GENERATED_HEADER = `// GENERATED by assemblejs build. Do not edit, and do not commit.
//
// The build writes this from the project's directories (src/assemblies, src/pages, src/api) on
// every build and every dev start, so the built server and the browser have a static import
// graph and nothing scans a directory at run time.
`;
